#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
TOTAL_MINUTES=100

mkdir -p build/watch-spike
ENV_FILE="build/watch-spike/spike.env"

banner "Спайк: компаньон «Склянки» на HUAWEI WATCH GT 6 Pro"

stage "AGC: приложение и сертификат" 5
say "Нужно убедиться, что Android-приложение есть в AppGallery Connect, и привязать к нему отпечаток релизной подписи."
open_url "https://developer.huawei.com/consumer/en/service/josp/agc/index.html"
step "Войди Huawei ID разработчика и открой проект «Склянка»."
step "Выбери приложение с пакетом ru.stohastika.sklyanka."
step "Открой Project settings → App information (название пункта может отличаться) и найди поле SHA-256 certificate fingerprint."
step "Вставь отпечаток релизного сертификата, если его там нет."
note "Отпечаток из документации проекта: 5c23349371a459889dbfae090212ee801c6cb161872f6966d339bb785c5cef0e (docs/archive/tasks/SKL-22/keystore.md §5)."
ask SHA256_RELEASE "Отпечаток SHA-256 релизной подписи:"
write_env SHA256_RELEASE "$SHA256_RELEASE"
pause "Готово? Enter."

stage "Консоль разработчика: заявка на Wear Engine" 10
say "Заявка живёт не в AppGallery Connect, а в HUAWEI Developers Console: App services > Development > Wear Engine."
open_url "https://developer.huawei.com/consumer/ru/console/service/AppService/service/1062"
step "Открой карточку Wear Engine и нажми «Apply for Wear Engine», прими соглашение."
step "Выбери Android app и приложение ru.stohastika.sklyanka."
step "Отметь два права: Basic device information (DEVICE_MANAGER) и Message notification (NOTIFY)."
step "Заполни описание данных и путь авторизации (черновик — build/watch-spike/wear-engine-application.md), отправь."
ask WEAR_ENGINE_APPLIED_AT "Дата отправки заявки (ГГГГ-ММ-ДД):"
write_env WEAR_ENGINE_APPLIED_AT "$WEAR_ENGINE_APPLIED_AT"
warn "Индивидуальному разработчику доступны только эти два права; одобрение обычно 1–2 недели."

stage "AGC: agconnect-services.json" 2
step "В том же приложении: Project settings → Download agconnect-services.json."
step "Положи файл по пути build/watch-spike/phone/app/agconnect-services.json — оттуда его берёт пробный Android-клиент."
warn "Если AGC открыт не в том чекауте, просто перенеси файл на Linux-машину в этот путь."
pause "Файл на месте? Enter."

stage "Mac: DevEco Studio и Lite Wearable проект" 30
open_url "https://developer.huawei.com/consumer/en/deveco-studio/"
step "Скачай сборку для macOS, установи, войди Huawei ID."
step "Create Project → Lite Wearable → шаблон на JS (пустой экран)."
step "bundleName: ru.stohastika.sklyanka.watch (ровно 28 символов — предел шаблонов)."
step "Build → Build Hap(s); готовый .hap обычно лежит в entry/build/outputs/hap/debug/."
ask HAP_PATH "Полный путь к собранному .hap:"
write_env HAP_PATH "$HAP_PATH"
if [[ -f "$HAP_PATH" ]]; then
  note "Файл найден."
else
  warn "Файла по этому пути нет — проверь, что сборка прошла и путь верный."
fi

stage "Часы: UDID и регистрация в AGC" 10
say "Установка на GT 6 идёт через телефон: DevEco Assistant → Lite Wearable → Connect."
open_url "https://developer.huawei.com/consumer/en/service/josp/agc/index.html#/harmonyOSDevPlatform/9249519184596237889"
step "На телефоне открой DevEco Assistant (поставь из AppGallery, если нет)."
step "Вкладка Lite Wearable → Connect → откроется Huawei Health → разреши и скопируй UDID часов."
step "В AGC: «Сертификаты, ID приложения и профили» → «Устройства» → добавить UDID."
ask WATCH_UDID "UDID часов:"
write_env WATCH_UDID "$WATCH_UDID"

stage "AGC: профиль отладки" 5
say "Профиль привязывает сертификат к часам и к имени пакета ru.stohastika.sklyanka.watch."
open_url "https://developer.huawei.com/consumer/en/service/josp/agc/index.html#/harmonyOSDevPlatform/172249065903274468"
step "«Сертификаты, ID приложения и профили» → «Профили» → «Добавить»."
step "Приложение «Склянка Часы», имя профиля sklyanka-watch-debug, тип «Отладка»."
step "Сертификат: sklyanka-watch-debug; устройство: только что добавленный UDID."
step "Сохрани и скачай .p7b в build/watch-spike/keys/."
ask PROFILE_PATH "Путь к скачанному .p7b:"
write_env PROFILE_PATH "$PROFILE_PATH"

stage "Часы: установка hello-world" 10
step "Создай на телефоне папку haps в корне внутренней памяти и скопируй туда .hap."
step "DevEco Assistant → Apps → выбери .hap → Install."
step "Запусти приложение на часах."
if confirm "Приложение запустилось на часах?"; then
  write_env HAP_INSTALLED yes
else
  write_env HAP_INSTALLED no
  warn "Запиши текст ошибки — он нужен в отчёте спайка."
fi

stage "Телефон: пробный Android-клиент" 5
say "Клиент лежит в build/watch-spike/phone (вне git, это выброшенный артефакт) и собирается на Linux-машине с репозиторием."
step "На Linux: ./gradlew -p build/watch-spike/phone assembleDebug"
step "Установи: adb install -r build/watch-spike/phone/app/build/outputs/apk/debug/app-debug.apk"
step "Открой приложение и нажми подряд: «Проверить часы», «Авторизовать», «Слушать», «Отправить ping»."
step "Вывод: adb logcat -d -s SklyankaWatchSpike"
ask SPIKE_SEND_RESULT "Что произошло при отправке ping (дошло / ошибка и код):"
write_env SPIKE_SEND_RESULT "$SPIKE_SEND_RESULT"

stage "Замеры" 15
say "Четыре факта решают, жизнеспособен ли компаньон."
ask WATCH_LATENCY_MS "Задержка ping → часы, мс (примерно):"
ask WATCH_AFTER_KILL "Команда с часов дошла при убитом процессе телефона (да/нет/не проверяли):"
ask WATCH_OFFLINE "Работает ли канал без Wi-Fi (да/нет):"
ask SNAPSHOT_FITS "Снапшот дня на 10 приёмов влез в 1 КБ (да/нет/не проверяли):"
write_env WATCH_LATENCY_MS "$WATCH_LATENCY_MS"
write_env WATCH_AFTER_KILL "$WATCH_AFTER_KILL"
write_env WATCH_OFFLINE "$WATCH_OFFLINE"
write_env SNAPSHOT_FITS "$SNAPSHOT_FITS"

finish
